const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const headers = raw.headers || {};
const query = raw.query || {};
const role = String(body.role || query.role || 'student').trim().toLowerCase();

let route = 1; // default: student
if (role.includes('teacher')) route = 0;
else if (role.includes('student')) route = 1;
else if (role.includes('parent')) route = 2;
else if (role.includes('assistant') || role.includes('admin')) route = 3;

return [{
  json: {
    headers,
    body,
    query,
    ...body,
    _route: route
  }
}];

const p = $('TEACHER: CODE | Parse Request1').first()?.json || $input.first().json;
return [{
  json: {
    success: true,
    authenticated: true,
    user_id: p.user_id || 'u-demo-teacher',
    full_name: p.full_name || 'أ. أحمد رضوان',
    email: p.email || 'teacher@eduflow.edu',
    roles: ["teacher","admin"],
    assistant_permissions: ["all"]
  }
}];

const ROLE = 'teacher';
const p = $('TEACHER: CODE | Parse Request1').first().json;
const a = $input.first().json;
const roles = a.roles || [];
const allowed = ROLE === 'teacher' ? (roles.includes('teacher') || roles.includes('admin')) : roles.includes(ROLE);
if (!allowed) return [{ json: { ok: false, code: 'FORBIDDEN', message: 'This assistant is not available for your account role' } }];
return [{ json: { ok: true, agent: ROLE, user_id: a.user_id, full_name: a.full_name, email: a.email, roles, assistant_permissions: a.assistant_permissions || [],
  access_token: p.access_token, message: p.message, group_id: p.group_id, conversation_id: p.conversation_id,
  memory_key: a.user_id + '_' + ROLE + '_' + p.conversation_id } }];

const raw = $input.first().json;
const h = raw.headers || {};
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const token = b.access_token || String(h.authorization || h.Authorization || '').replace(/^Bearer\s+/i, '').trim() || 'eduflow-token';
const message = typeof b.message === 'string' && b.message.trim() ? b.message.trim() : (typeof b.query === 'string' && b.query.trim() ? b.query.trim() : 'مرحباً، أحتاج إلى مساعدة دراسية');
return [{
  json: {
    valid: true,
    access_token: token,
    message,
    conversation_id: b.conversation_id || b.session_id || 'default-chat',
    group_id: b.group_id || null,
    mode: b.mode || null,
    role: b.role || 'student'
  }
}];

const j = $input.first().json;
const map = { UNAUTHENTICATED: 401, FORBIDDEN: 403, NOT_FOUND: 404, VALIDATION: 400, UPSTREAM_ERROR: 502, NEEDS_CONFIRMATION: 409, RETRYABLE: 503 };
const code = j.code || (j.success ? 'OK' : 'FORBIDDEN');
return [{ json: { ...j, http_status: j.success ? (j.http_status || 200) : (map[code] || 400) } }];

